BEGIN TRANSACTION;
CREATE TABLE accounts (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, currency TEXT NOT NULL);
CREATE TABLE events (account_id TEXT NOT NULL REFERENCES accounts(id), sequence INTEGER NOT NULL, event_id TEXT NOT NULL, run_id TEXT REFERENCES runs(id), time_ns INTEGER, kind TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(account_id, sequence), UNIQUE(account_id, event_id));
CREATE TABLE makers (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, kind TEXT NOT NULL, version TEXT NOT NULL, config TEXT NOT NULL);
CREATE TABLE profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), maker_id TEXT NOT NULL REFERENCES makers(id), status TEXT NOT NULL, time_ns INTEGER NOT NULL, universe TEXT NOT NULL, config TEXT NOT NULL, initial_snapshot TEXT NOT NULL, policy_state TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_run ON runs(account_id) WHERE status='running';
COMMIT;
PRAGMA application_id = 1414745393;
PRAGMA user_version = 1;
